    if (depth + radius < c.Near || depth - radius > c.Far ||
        Dot(d, c.P[2].N) > radius || Dot(d, c.P[3].N) > radius ||
        Dot(d, c.P[0].N) > radius || Dot(d, c.P[1].N) > radius)
        return false;
    return true;
}

